         WHERE UP_SRVY_ID = #{srvyId}

mapper.select:
/* SQL ID : SrvyDAO.profAuthrtSbjctSrvyList 설 명 : 교수권한과목설문목록조회 */ SELECT ROW_NUMBER() OVER(ORDER BY SRVY.SRVY_ID DESC) AS LINE_NO , SRVY.SRVY_ID , SRVY.SRVY_TTL , SBJCT.SBJCT_ID , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , CASE WHEN EXISTS ( SELECT 1 FROM TB_LMS_SRVY SS WHERE SS.UP_SRVY_ID = SRVY.SRVY_ID AND SS.DELYN = 'N' AND SS.USEYN = 'Y' ) THEN 'SRVY_TEAM' ELSE 'SRVY' END AS SRVY_GBN , (SELECT SRVY_ID FROM TB_LMS_SRVY WHERE UP_SRVY_ID = SRVY.SRVY_ID AND DELYN = 'N' AND USEYN = 'Y' AND ROWNUM = 1) AS SUB_SRVY_ID , COUNT(1) OVER() AS TOTAL_CNT FROM TB_LMS_SBJCT_ADM SBJCT_ADM JOIN TB_LMS_SRVY SRVY ON SBJCT_ADM.SBJCT_ID = SRVY.SBJCT_ID AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' JOIN TB_LMS_SBJCT SBJCT ON SBJCT.SBJCT_ID = SRVY.SBJCT_ID LEFT JOIN TB_LMS_SMSTR_CHRT SMSTR_CHRT ON (SBJCT.SMSTR_CHRT_ID = SMSTR_CHRT.SMSTR_CHRT_ID AND SBJCT.SBJCT_REF_TYCD = 'CHRT') WHERE SBJCT_ADM.USER_ID = #{userId} AND SRVY.SRVY_GBNCD = 'LCTR_SRVY' AND SRVY.UP_SRVY_ID IS NULL AND SBJCT_ADM.SBJCT_ADM_TYCD = 'PROF' AND SRVY.SRVY_QSTNS_CMPTNYN = 'Y'
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
AND SBJCT.SBJCT_ID = #{sbjctId}
AND LOWER(SRVY.SRVY_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
ORDER BY SRVY.SRVY_ID

/* SQL ID : SrvyDAO.stdntSrvyListPaging 설 명 : 학생설문목록페이징 */
WITH USER_TEAM AS ( /* 사용자 팀목록 */ SELECT TEAM_ID FROM TB_LMS_TEAM_MBR WHERE USER_ID = #{userId} ), SRVY_BASE AS ( /* 기본 설문 정보 */ SELECT SRVY.SRVY_ID AS UP_SRVY_ID , SRVY.SBJCT_ID , CASE WHEN SUB.SRVY_ID IS NOT NULL THEN 'SRVY_TEAM' ELSE 'SRVY' END AS SRVY_GBN , SRVY.SRVY_TTL , SRVY.SRVY_SDTTM , SRVY.SRVY_EDTTM , SRVY.MRK_RFLTYN , SRVY.MRK_OYN , SRVY.SRVY_QSTNS_CMPTNYN , SRVY.REG_DTTM , NVL(PTCP.PTCP_EVL_SCR, 0) AS PTCP_EVL_SCR , NVL(PTCP.SRVY_PTCP_EVLYN, 'N') AS SRVY_PTCP_EVLYN , PTCP.SRVY_PTCP_ID , PTCP.PTCP_SDTTM , PTCP.PTCP_EDTTM , NVL(TRGT.SRVY_ID, SRVY.SRVY_ID) AS SRVY_ID FROM TB_LMS_SRVY SRVY JOIN TB_LMS_ATNDLC ATNDLC ON ATNDLC.SBJCT_ID = SRVY.SBJCT_ID AND ATNDLC.USER_ID = #{userId} AND ATNDLC.ATNDLC_STSCD = 'APPROVE' LEFT JOIN TB_LMS_SRVY SUB ON SUB.UP_SRVY_ID = SRVY.SRVY_ID AND SUB.DELYN = 'N' AND SUB.USEYN = 'Y' LEFT JOIN TB_LMS_SRVY_TRGT TRGT ON TRGT.SRVY_ID = SUB.SRVY_ID AND TRGT.TEAM_ID IN (SELECT TEAM_ID FROM USER_TEAM) LEFT JOIN TB_LMS_SRVY_PTCP PTCP ON PTCP.SRVY_ID = NVL(SUB.SRVY_ID, SRVY.SRVY_ID) AND PTCP.USER_ID = #{userId} WHERE SRVY.SBJCT_ID = #{sbjctId} AND SRVY.SRVY_GBNCD = 'LCTR_SRVY' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND SRVY.SRVY_QSTNS_CMPTNYN = 'Y' AND SRVY.UP_SRVY_ID IS NULL
AND LOWER(SRVY.SRVY_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
) SELECT SRVY.* , ROW_NUMBER() OVER(ORDER BY SRVY.SRVY_SDTTM DESC, SRVY.REG_DTTM ASC) AS LINE_NO , COUNT(*) OVER() AS TOTAL_CNT , CASE WHEN SYSDATE BETWEEN TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') AND TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'IN_PROGRESS' WHEN SYSDATE < TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') THEN 'PRE_SRVY' WHEN SYSDATE > TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'DONE' ELSE 'ERROR' END AS SRVY_PRGRS_STS FROM SRVY_BASE SRVY WHERE ( (SRVY.SRVY_GBN = 'SRVY_TEAM' AND SRVY.UP_SRVY_ID <> SRVY.SRVY_ID) OR SRVY.SRVY_GBN = 'SRVY' )

/* SQL ID : SrvyDAO.admSrvyLctrEvlListPaging 설 명 : 관리자설문강의평가목록페이징 */
WITH SUB_SRVY AS ( -- 상위 설문에 연결된 하위(과목별) 설문 집계 SELECT SRVY.UP_SRVY_ID, COUNT(*) AS SBJCT_CNT, MAX(ORG.ORGNM) AS ORGNM FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SBJCT SBJCT ON SRVY.SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJCT.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID
JOIN TB_LMS_USER USR ON USR.USER_ID_STSCD = 'APRV_CMPTN' AND USR.USER_TYCD = 'ADM' AND USR.USER_ID = #{userId} JOIN TB_LMS_USER_AUTHRT USR_AUTHRT ON USR_AUTHRT.USER_ID = USR.USER_ID JOIN TB_LMS_AUTHRT AUTHRT ON AUTHRT.AUTHRT_ID = USR_AUTHRT.AUTHRT_ID AND AUTHRT.AUTHRT_ID = 'AUTHRT_ID00012'
WHERE SRVY.SRVY_GBNCD = 'LCTR_SRVY' AND SRVY.SRVY_TYCD LIKE '%EXAM%' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND CHRT.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND CHRT.DGRS_YR = #{dgrsYr}
AND SRVY.UP_SRVY_ID IS NOT NULL GROUP BY SRVY.UP_SRVY_ID ) SELECT A.* , ROW_NUMBER() OVER (ORDER BY A.REG_DTTM DESC) AS LINE_NO , COUNT(A.SRVY_ID) OVER() AS TOTAL_CNT FROM ( SELECT SRVY.*, WRT_CD.CDNM AS SRVY_WRT_TYNM, TRGT_CD.CDNM AS SRVY_TRGT_GBNNM, SUB_SRVY.SBJCT_CNT, SUB_SRVY.ORGNM, CASE WHEN SYSDATE BETWEEN TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') AND TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'IN_PROGRESS' WHEN SYSDATE < TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') THEN 'PRE_SRVY' WHEN SYSDATE > TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'DONE' ELSE 'ERROR' END AS SRVY_PRGRS_STS FROM TB_LMS_SRVY SRVY JOIN SUB_SRVY ON SRVY.SRVY_ID = SUB_SRVY.UP_SRVY_ID LEFT JOIN TB_LMS_CMMN_CD WRT_CD ON WRT_CD.UP_CD = 'SRVY_WRT_TYCD' AND WRT_CD.CD = SRVY.SRVY_WRT_TYCD LEFT JOIN TB_LMS_CMMN_CD TRGT_CD ON TRGT_CD.UP_CD = 'SRVY_TRGT_GBNCD' AND TRGT_CD.CD = SRVY.SRVY_TRGT_GBNCD WHERE SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y'
AND LOWER(SRVY.SRVY_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
) A

/* SQL ID : SrvyDAO.srvyLctrEvlNRegistSbjctList 설 명 : 설문강의평가미등록과목목록 */ WITH SBJCT_ADM_1ST AS ( -- 과목별 담당교수(PROF)/조교(TUT) 각 1명 SELECT SBJCT_ID, SBJCT_ADM_TYCD, USER_ID, ROW_NUMBER() OVER (PARTITION BY SBJCT_ID, SBJCT_ADM_TYCD ORDER BY SBJCT_ADM_SEQNO ASC) AS RNUM FROM TB_LMS_SBJCT_ADM WHERE SBJCT_ADM_TYCD IN ('PROF', 'TUT') ) SELECT ORG.ORGNM, SBJCT.SBJCT_ID, SBJCT.CRCLMN_NO AS SBJCT_CD, SBJCT.SBJCTNM, SBJCT.DVCLAS_NO, PROF_USR.USERNM AS PROFNM, TUT_USR.USERNM AS TUTNM FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJCT.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID LEFT JOIN SBJCT_ADM_1ST PROF_ADM ON PROF_ADM.SBJCT_ID = SBJCT.SBJCT_ID AND PROF_ADM.SBJCT_ADM_TYCD = 'PROF' AND PROF_ADM.RNUM = 1 LEFT JOIN TB_LMS_USER PROF_USR ON PROF_USR.USER_ID = PROF_ADM.USER_ID LEFT JOIN SBJCT_ADM_1ST TUT_ADM ON TUT_ADM.SBJCT_ID = SBJCT.SBJCT_ID AND TUT_ADM.SBJCT_ADM_TYCD = 'TUT' AND TUT_ADM.RNUM = 1 LEFT JOIN TB_LMS_USER TUT_USR ON TUT_USR.USER_ID = TUT_ADM.USER_ID WHERE SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' AND CHRT.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND CHRT.DGRS_YR = #{dgrsYr}
AND NOT EXISTS ( SELECT 1 FROM TB_LMS_SRVY SRVY WHERE SRVY.SBJCT_ID = SBJCT.SBJCT_ID AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND SRVY.SRVY_GBNCD = 'LCTR_SRVY' AND SRVY.UP_SRVY_ID IS NOT NULL AND SRVY.SRVY_TYCD = #{srvyTycd}
AND SRVY.UP_SRVY_ID <> #{srvyId}
) ORDER BY CHRT.ORG_ID, SBJCT.SBJCTNM, SBJCT.DVCLAS_NO

mapper.insert:
		/*
             SQL ID : SrvyDAO.srvyBulkRegist
             설  명 : 설문일괄등록
         */
         INSERT ALL

			INTO TB_LMS_SRVY (
	         	  SRVY_ID
				, SRVY_GRP_ID
				, SBJCT_ID
				, LCTR_WKNO_SCHDL_ID
				, UP_SRVY_ID
				, SRVY_WRT_TYCD
				, SRVY_GBNCD
				, SRVY_TYCD
				, SRVY_TRGT_GBNCD
				, SRVY_TTL
				, SRVY_CTS
				, RSLT_OPEN_TYCD
				, DVCLAS_REGYN
				, SRVY_SDTTM
				, SRVY_EDTTM
				, EVL_SCR_TYCD
				, MRK_RFLTYN
				, MRK_RFLTRT
				, MRK_OYN
				, BYTEAM_SUBSRVY_USEYN
				, RGTR_ID
				, REG_DTTM
	         ) VALUES (
	         	  #{item.srvyId}
				, #{item.srvyGrpId}
				, #{item.sbjctId}
				, #{item.lctrWknoSchdlId}
				, #{item.upSrvyId}
				, #{item.srvyWrtTycd}
				, #{item.srvyGbncd}
				, #{item.srvyTycd}
				, #{item.srvyTrgtGbncd}
				, #{item.srvyTtl}
				, #{item.srvyCts}
				, #{item.rsltOpenTycd}
				, #{item.dvclasRegyn}
				, #{item.srvySdttm}
				, #{item.srvyEdttm}
				, #{item.evlScrTycd}
				, #{item.mrkRfltyn}
				, #{item.mrkRfltrt}
				, #{item.mrkOyn}
				, #{item.byteamSubsrvyUseyn}
				, #{item.rgtrId}
				, FN_DTTM()
	         )

		SELECT * FROM DUAL

mapper.select:
/* SQL ID : SrvyDAO.srvyLctrEvlSelect 설 명 : 설문강의평가조회 */ SELECT SRVY.SRVY_ID , SRVY.SRVY_TRGT_GBNCD , SRVY.SRVY_TTL , SRVY.SRVY_CTS , SRVY.SRVY_TYCD , SRVY.SRVY_SDTTM , SRVY.SRVY_EDTTM , SRVY.SRVY_WRT_TYCD , SRVY.MRK_OYN , SRVY.RSLT_OPEN_TYCD , SRVY.SRVY_QSTNS_CMPTNYN , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'SRVY_WRT_TYCD' AND CD = SRVY.SRVY_WRT_TYCD) AS SRVY_WRT_TYNM , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'SRVY_TRGT_GBNCD' AND CD = SRVY.SRVY_TRGT_GBNCD) AS SRVY_TRGT_GBNNM , SUB_SRVY.SBJCT_CNT , SUB_SRVY.ORG_ID , SUB_SRVY.ORGNM , SUB_SRVY.DGRS_YR , SUB_SRVY.SMSTR_CHRT_ID , SUB_SRVY.SMSTR_CHRTNM , CASE WHEN SYSDATE BETWEEN TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') AND TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'IN_PROGRESS' WHEN SYSDATE < TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') THEN 'PRE_SRVY' WHEN SYSDATE > TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'DONE' ELSE 'ERROR' END AS SRVY_PRGRS_STS FROM TB_LMS_SRVY SRVY JOIN ( SELECT SRVY.UP_SRVY_ID , COUNT(*) AS SBJCT_CNT , MAX(ORG.ORG_ID) AS ORG_ID , MAX(ORG.ORGNM) AS ORGNM , MAX(CHRT.DGRS_YR) AS DGRS_YR , MAX(CHRT.SMSTR_CHRT_ID) AS SMSTR_CHRT_ID , MAX(CHRT.SMSTR_CHRTNM) AS SMSTR_CHRTNM FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SBJCT SBJCT ON SRVY.SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJCT.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID WHERE SRVY.SRVY_GBNCD = 'LCTR_SRVY' AND SRVY.SRVY_TYCD LIKE '%EXAM%' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND SRVY.UP_SRVY_ID IS NOT NULL
AND ORG.ORG_ID = #{orgId}
GROUP BY SRVY.UP_SRVY_ID ) SUB_SRVY ON SRVY.SRVY_ID = SUB_SRVY.UP_SRVY_ID WHERE SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND SRVY.SRVY_ID = #{srvyId}

/* SQL ID : SrvyDAO.srvyLctrEvlRegistSbjctList 설 명 : 설문강의평가등록과목목록 */ SELECT ORG.ORGNM , SBJCT.SBJCT_ID , SBJCT.CRCLMN_NO AS SBJCT_CD , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , (SELECT USERNM FROM TB_LMS_USER WHERE USER_ID = (SELECT USER_ID FROM TB_LMS_SBJCT_ADM WHERE SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT_ADM_TYCD = 'PROF' AND ROWNUM = 1)) AS PROFNM , (SELECT USERNM FROM TB_LMS_USER WHERE USER_ID = (SELECT USER_ID FROM TB_LMS_SBJCT_ADM WHERE SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT_ADM_TYCD = 'TUT' AND ROWNUM = 1)) AS TUTNM FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SBJCT SBJCT ON SRVY.SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJCT.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID
AND ORG.ORG_ID = #{orgId}
/* 과목관리자용 */ JOIN TB_LMS_USER USR ON USR.USER_ID_STSCD = 'APRV_CMPTN' AND USR.USER_TYCD = 'ADM' AND USR.USER_ID = #{userId} JOIN TB_LMS_USER_AUTHRT USR_AUTHRT ON USR_AUTHRT.USER_ID = USR.USER_ID JOIN TB_LMS_AUTHRT AUTHRT ON AUTHRT.AUTHRT_ID = USR_AUTHRT.AUTHRT_ID AND AUTHRT.AUTHRT_ID = 'AUTHRT_ID00012'
WHERE SRVY.SRVY_GBNCD = 'LCTR_SRVY' AND SRVY.SRVY_TYCD LIKE '%EXAM%' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND SRVY.UP_SRVY_ID = #{srvyId}

/* SQL ID : SrvyDAO.copySrvyLctrEvlList 설 명 : 가져오기설문강의평가목록 */ SELECT SRVY.* , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'SRVY_WRT_TYCD' AND CD = SRVY.SRVY_WRT_TYCD) AS SRVY_WRT_TYNM , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'SRVY_TRGT_GBNCD' AND CD = SRVY.SRVY_TRGT_GBNCD) AS SRVY_TRGT_GBNNM , SUB_SRVY.ORGNM , ROW_NUMBER() OVER(ORDER BY SRVY.SRVY_TTL) AS LINE_NO FROM TB_LMS_SRVY SRVY JOIN ( SELECT SRVY.UP_SRVY_ID , MAX(ORG.ORGNM) AS ORGNM FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SBJCT SBJCT ON SRVY.SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJCT.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID WHERE SRVY.SRVY_GBNCD = 'LCTR_SRVY' AND SRVY.SRVY_TYCD LIKE '%EXAM%' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND CHRT.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND SRVY.UP_SRVY_ID IS NOT NULL GROUP BY SRVY.UP_SRVY_ID ) SUB_SRVY ON SRVY.SRVY_ID = SUB_SRVY.UP_SRVY_ID WHERE SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y'
AND LOWER(SRVY.SRVY_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
AND SRVY.SRVY_TRGT_GBNCD = #{srvyTrgtGbncd}
AND SRVY.SRVY_ID <> #{srvyId}
AND SRVY.SRVY_QSTNS_CMPTNYN = #{srvyQstnsCmptnyn}

/* SQL ID : SrvyDAO.admSrvyLctrEvlRsltListPaging 설 명 : 관리자설문강의평가결과목록페이징 */
SELECT ROW_NUMBER() OVER(ORDER BY SRVY.USERNM) AS LINE_NO , SRVY.* , COUNT(SRVY.SRVY_ID) OVER() AS TOTAL_CNT FROM ( SELECT SRVY.SRVY_ID , ORG.ORGNM , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'USER_TYCD' AND CD = USR.USER_TYCD) AS USER_TYNM , USR.USER_ID , USR.USERNM , PTCP.PTCP_SDTTM , PTCP.PTCP_EDTTM FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SBJCT SBJCT ON SRVY.SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJCT.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID
/* 과목관리자용 */ JOIN TB_LMS_USER ADM ON ADM.USER_ID_STSCD = 'APRV_CMPTN' AND ADM.USER_TYCD = 'ADM' AND ADM.USER_ID = #{userId} JOIN TB_LMS_USER_AUTHRT USR_AUTHRT ON USR_AUTHRT.USER_ID = ADM.USER_ID JOIN TB_LMS_AUTHRT AUTHRT ON AUTHRT.AUTHRT_ID = USR_AUTHRT.AUTHRT_ID AND AUTHRT.AUTHRT_ID = 'AUTHRT_ID00012'
JOIN TB_LMS_ATNDLC ATNDLC ON SBJCT.SBJCT_ID = ATNDLC.SBJCT_ID AND ATNDLC.AUDITYN = 'N' JOIN TB_LMS_USER USR ON ATNDLC.USER_ID = USR.USER_ID AND USR.USER_ID_STSCD = 'APRV_CMPTN' LEFT JOIN TB_LMS_SRVY_PTCP PTCP ON SRVY.SRVY_ID = PTCP.SRVY_ID AND USR.USER_ID = PTCP.USER_ID WHERE SRVY.UP_SRVY_ID = #{srvyId} AND SRVY.SRVY_GBNCD = 'LCTR_SRVY' AND SRVY.SRVY_TYCD LIKE '%EXAM%' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y'
AND ORG.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND SBJCT.SBJCT_ID = #{sbjctId}
AND PTCP.PTCP_EDTTM IS NOT NULL
AND PTCP.PTCP_EDTTM IS NULL
AND ( LOWER(USR.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(USR.USER_ID) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
) SRVY

/* SQL ID : SrvyDAO.admSrvyListPaging 설 명 : 관리자전체설문목록페이징 */
SELECT ROW_NUMBER() OVER(ORDER BY SRVY.REG_DTTM DESC) AS LINE_NO , SRVY.* , COUNT(SRVY.SRVY_ID) OVER() AS TOTAL_CNT FROM ( SELECT SRVY.* , TRGT.SRVY_TRGT_TYCD , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'USER_TYCD' AND CD = TRGT.SRVY_TRGT_TYCD) AS SRVY_TRGT_TYNM , ORG.ORGNM , CASE WHEN SYSDATE BETWEEN TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') AND TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'IN_PROGRESS' WHEN SYSDATE < TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') THEN 'PRE_SRVY' WHEN SYSDATE > TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'DONE' ELSE 'ERROR' END AS SRVY_PRGRS_STS FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SRVY_TRGT TRGT ON SRVY.SRVY_ID = TRGT.SRVY_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON SRVY.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID WHERE SRVY.SRVY_GBNCD = 'HOMEPAGE_SRVY' AND SRVY.SRVY_TYCD = 'SRVY_WHOL' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND CHRT.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND CHRT.DGRS_YR = #{dgrsYr}
AND LOWER(SRVY.SRVY_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
) SRVY

/* SQL ID : SrvyDAO.copySrvyList 설 명 : 가져오기전체설문목록 */ SELECT SRVY.* , TRGT.SRVY_TRGT_TYCD , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'USER_TYCD' AND CD = TRGT.SRVY_TRGT_TYCD) AS SRVY_TRGT_TYNM , ORG.ORGNM , ROW_NUMBER() OVER(ORDER BY SRVY.SRVY_TTL) AS LINE_NO FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SRVY_TRGT TRGT ON SRVY.SRVY_ID = TRGT.SRVY_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON SRVY.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID WHERE SRVY.SRVY_GBNCD = 'HOMEPAGE_SRVY' AND SRVY.SRVY_TYCD = 'SRVY_WHOL' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND CHRT.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND CHRT.DGRS_YR = #{dgrsYr}
AND LOWER(SRVY.SRVY_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
AND TRGT.SRVY_TRGT_TYCD = #{srvyTrgtTycd}
AND SRVY.SRVY_ID <> #{srvyId}
AND SRVY.SRVY_QSTNS_CMPTNYN = #{srvyQstnsCmptnyn}

/* SQL ID : SrvyDAO.admSrvyRsltListPaging 설 명 : 관리자전체설문결과목록페이징 */
SELECT ROW_NUMBER() OVER(ORDER BY SRVY.DEPTNM, SRVY.USERNM) AS LINE_NO , SRVY.* , COUNT(SRVY.SRVY_ID) OVER() AS TOTAL_CNT FROM ( SELECT SRVY.* , DEPT.DEPTNM , PTCP.PTCP_SDTTM , PTCP.PTCP_EDTTM FROM ( SELECT DISTINCT SRVY.SRVY_ID , ORG.ORGNM , ORG.ORG_ID , COALESCE(STDNT.USER_ID, PROF.USER_ID, ADM.USER_ID) AS USER_ID , COALESCE(STDNT.USERNM, PROF.USERNM, ADM.USERNM) AS USERNM , COALESCE(STDNT.DEPT_ID, PROF.DEPT_ID, ADM.DEPT_ID) AS DEPT_ID , AUTHRT.AUTHRTNM FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SRVY_TRGT TRGT ON SRVY.SRVY_ID = TRGT.SRVY_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON SRVY.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID JOIN TB_LMS_AUTHRT AUTHRT ON CASE WHEN TRGT.SRVY_TRGT_TYCD = 'ALL' THEN '1' WHEN TRGT.SRVY_TRGT_TYCD = 'ADM' THEN AUTHRT.AUTHRT_GRPCD ELSE AUTHRT.AUTHRT_CD END LIKE CASE WHEN TRGT.SRVY_TRGT_TYCD = 'ALL' THEN '1' ELSE FN_LIKE_VAL(TRGT.SRVY_TRGT_TYCD) END AND AUTHRT.AUTHRT_CD NOT IN ('AUDIT', 'OBSVR', 'GUEST') JOIN TB_LMS_USER_AUTHRT USR_AUTHRT ON AUTHRT.AUTHRT_ID = USR_AUTHRT.AUTHRT_ID JOIN TB_LMS_SBJCT SBJCT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID AND SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' LEFT JOIN TB_LMS_ATNDLC ATNDLC ON SBJCT.SBJCT_ID = ATNDLC.SBJCT_ID AND ATNDLC.AUDITYN = 'N' AND USR_AUTHRT.USER_ID = ATNDLC.USER_ID LEFT JOIN TB_LMS_SBJCT_ADM SBJCT_ADM ON SBJCT.SBJCT_ID = SBJCT_ADM.SBJCT_ID AND SBJCT_ADM.SBJCT_ADM_TYCD LIKE FN_LIKE_VAL(TRGT.SRVY_TRGT_TYCD) AND USR_AUTHRT.USER_ID = SBJCT_ADM.USER_ID LEFT JOIN TB_LMS_USER STDNT ON ATNDLC.USER_ID = STDNT.USER_ID AND STDNT.USER_ID_STSCD = 'APRV_CMPTN' LEFT JOIN TB_LMS_USER PROF ON SBJCT_ADM.USER_ID = PROF.USER_ID AND PROF.USER_ID_STSCD = 'APRV_CMPTN' LEFT JOIN TB_LMS_USER ADM ON USR_AUTHRT.USER_ID = ADM.USER_ID WHERE SRVY.SRVY_GBNCD = 'HOMEPAGE_SRVY' AND SRVY.SRVY_TYCD = 'SRVY_WHOL' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND SRVY.SRVY_ID = #{srvyId}
AND ORG.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND TRGT.SRVY_TRGT_TYCD = #{srvyTrgtTycd}
) SRVY LEFT JOIN TB_LMS_DEPT DEPT ON SRVY.DEPT_ID = DEPT.DEPT_ID AND SRVY.ORG_ID = DEPT.ORG_ID LEFT JOIN TB_LMS_SRVY_PTCP PTCP ON SRVY.SRVY_ID = PTCP.SRVY_ID AND SRVY.USER_ID = PTCP.USER_ID
AND ( LOWER(SRVY.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(SRVY.USER_ID) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
) SRVY WHERE 1 = 1
AND SRVY.PTCP_EDTTM IS NOT NULL
AND SRVY.PTCP_EDTTM IS NULL

/* SQL ID : SrvyDAO.stdntMainSrvyLctrEvlList 설 명 : 학생대시보드설문강의평가목록조회 */ SELECT ROW_NUMBER() OVER(ORDER BY SBJCT.SBJCT_YR, SBJCT.SBJCT_SMSTR, SBJCT.SBJCT_ID) AS LINE_NO , SBJCT.SBJCT_YR , SBJCT.SBJCT_SMSTR , ORG.ORGNM , SBJCT.SBJCT_ID , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , SBJCT.CRDTS , (SELECT USR.USERNM FROM TB_LMS_SBJCT_ADM ADM JOIN TB_LMS_USER USR ON ADM.USER_ID = USR.USER_ID WHERE ADM.SBJCT_ID = SBJCT.SBJCT_ID AND ADM.SBJCT_ADM_TYCD = 'PROF' AND ROWNUM = 1) AS PROFNM , (SELECT USR.USERNM FROM TB_LMS_SBJCT_ADM ADM JOIN TB_LMS_USER USR ON ADM.USER_ID = USR.USER_ID WHERE ADM.SBJCT_ID = SBJCT.SBJCT_ID AND ADM.SBJCT_ADM_TYCD = 'TUT' AND ROWNUM = 1) AS TUTNM , (SELECT USR.USERNM FROM TB_LMS_SBJCT_ADM ADM JOIN TB_LMS_USER USR ON ADM.USER_ID = USR.USER_ID WHERE ADM.SBJCT_ID = SBJCT.SBJCT_ID AND ADM.SBJCT_ADM_TYCD = 'ASSI' AND ROWNUM = 1) AS ASSINM , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_MIDEXAM_AFTR_LCTR_EVL' THEN (SELECT UP_SRVY_ID FROM TB_LMS_SRVY WHERE SRVY_ID = SRVY.SRVY_ID) END) AS MID_UP_SRVY_ID , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_MIDEXAM_AFTR_LCTR_EVL' THEN SRVY.SRVY_ID END) AS MID_SRVY_ID , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_MIDEXAM_AFTR_LCTR_EVL' THEN (SELECT SRVY_PTCP_ID FROM TB_LMS_SRVY_PTCP WHERE SRVY_ID = SRVY.SRVY_ID AND USER_ID = #{userId}) END) AS MID_SRVY_PTCP_ID , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_MIDEXAM_AFTR_LCTR_EVL' THEN (SELECT PTCP_SDTTM FROM TB_LMS_SRVY_PTCP WHERE SRVY_ID = SRVY.SRVY_ID AND USER_ID = #{userId}) END) AS MID_PTCP_SDTTM , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_MIDEXAM_AFTR_LCTR_EVL' THEN (SELECT PTCP_EDTTM FROM TB_LMS_SRVY_PTCP WHERE SRVY_ID = SRVY.SRVY_ID AND USER_ID = #{userId}) END) AS MID_PTCP_EDTTM , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_MIDEXAM_AFTR_LCTR_EVL' THEN CASE WHEN SYSDATE BETWEEN TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') AND TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'IN_PROGRESS' WHEN SYSDATE < TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') THEN 'PRE_SRVY' WHEN SYSDATE > TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'DONE' ELSE 'ERROR' END END) AS MID_SRVY_PRGRS_STS , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_MIDEXAM_AFTR_LCTR_EVL' THEN SRVY.RSLT_OPEN_TYCD END) AS MID_RSLT_OPEN_TYCD , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_LSTEXAM_AFTR_LCTR_EVL' THEN (SELECT UP_SRVY_ID FROM TB_LMS_SRVY WHERE SRVY_ID = SRVY.SRVY_ID) END) AS LST_UP_SRVY_ID , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_LSTEXAM_AFTR_LCTR_EVL' THEN SRVY.SRVY_ID END) AS LST_SRVY_ID , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_LSTEXAM_AFTR_LCTR_EVL' THEN (SELECT SRVY_PTCP_ID FROM TB_LMS_SRVY_PTCP WHERE SRVY_ID = SRVY.SRVY_ID AND USER_ID = #{userId}) END) AS LST_SRVY_PTCP_ID , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_LSTEXAM_AFTR_LCTR_EVL' THEN (SELECT PTCP_SDTTM FROM TB_LMS_SRVY_PTCP WHERE SRVY_ID = SRVY.SRVY_ID AND USER_ID = #{userId}) END) AS LST_PTCP_SDTTM , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_LSTEXAM_AFTR_LCTR_EVL' THEN (SELECT PTCP_EDTTM FROM TB_LMS_SRVY_PTCP WHERE SRVY_ID = SRVY.SRVY_ID AND USER_ID = #{userId}) END) AS LST_PTCP_EDTTM , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_LSTEXAM_AFTR_LCTR_EVL' THEN CASE WHEN SYSDATE BETWEEN TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') AND TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'IN_PROGRESS' WHEN SYSDATE < TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') THEN 'PRE_SRVY' WHEN SYSDATE > TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'DONE' ELSE 'ERROR' END END) AS LST_SRVY_PRGRS_STS , MAX(CASE WHEN SRVY.SRVY_TYCD = 'SRVY_LSTEXAM_AFTR_LCTR_EVL' THEN SRVY.RSLT_OPEN_TYCD END) AS LST_RSLT_OPEN_TYCD FROM TB_LMS_SRVY SRVY JOIN TB_LMS_ATNDLC ATNDLC ON SRVY.SBJCT_ID = ATNDLC.SBJCT_ID AND ATNDLC.AUDITYN = 'N' AND ATNDLC.USER_ID = #{userId} JOIN TB_LMS_SBJCT SBJCT ON SRVY.SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJCT.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID WHERE SRVY.SRVY_GBNCD = 'LCTR_SRVY' AND SRVY.SRVY_TYCD LIKE '%EXAM%' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y'
AND CHRT.DGRS_YR = #{dgrsYr}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND ORG.ORG_ID = #{orgId}
AND SBJCT.SBJCT_ID = #{sbjctId}
GROUP BY SBJCT.SBJCT_YR , SBJCT.SBJCT_SMSTR , ORG.ORGNM , SBJCT.SBJCT_ID , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , SBJCT.CRDTS ORDER BY SBJCT.SBJCT_YR, SBJCT.SBJCT_SMSTR, SBJCT.SBJCT_ID

/* SQL ID : SrvyDAO.trgtWholSrvyListPaging 설 명 : 대상전체설문목록페이징 */
SELECT ROW_NUMBER() OVER(ORDER BY SRVY.SRVY_SDTTM, SRVY.SRVY_EDTTM) AS LINE_NO , COUNT(SRVY.SRVY_ID) OVER() AS TOTAL_CNT , CHRT.DGRS_YR , CHRT.DGRS_SMSTR_CHRT , ORG.ORGNM , SRVY.SRVY_ID , SRVY.SRVY_TTL , SRVY.SRVY_SDTTM , SRVY.SRVY_EDTTM , (SELECT COUNT(QSTN.SRVY_QSTN_ID) FROM TB_LMS_SRVY_QSTN QSTN JOIN TB_LMS_SRVYPPR PPR ON QSTN.SRVYPPR_ID = PPR.SRVYPPR_ID WHERE QSTN.DELYN = 'N' AND PPR.SRVY_ID = SRVY.SRVY_ID) AS QSTN_CNT , SRVY.RSLT_OPEN_TYCD , CASE WHEN SYSDATE BETWEEN TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') AND TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'IN_PROGRESS' WHEN SYSDATE < TO_DATE(SRVY.SRVY_SDTTM, 'YYYYMMDDHH24MISS') THEN 'PRE_SRVY' WHEN SYSDATE > TO_DATE(SRVY.SRVY_EDTTM, 'YYYYMMDDHH24MISS') THEN 'DONE' ELSE 'ERROR' END AS SRVY_PRGRS_STS , PTCP.SRVY_PTCP_ID , PTCP.PTCP_SDTTM , PTCP.PTCP_EDTTM FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SMSTR_CHRT CHRT ON SRVY.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID LEFT JOIN TB_LMS_SRVY_PTCP PTCP ON PTCP.SRVY_ID = SRVY.SRVY_ID AND PTCP.USER_ID = #{userId} WHERE SRVY.SRVY_ID IN ( SELECT SRVY.SRVY_ID FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SRVY_TRGT TRGT ON SRVY.SRVY_ID = TRGT.SRVY_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON SRVY.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID JOIN TB_LMS_AUTHRT AUTHRT ON CASE WHEN TRGT.SRVY_TRGT_TYCD = 'ALL' THEN '1' WHEN TRGT.SRVY_TRGT_TYCD = 'ADM' THEN AUTHRT.AUTHRT_GRPCD ELSE AUTHRT.AUTHRT_CD END LIKE CASE WHEN TRGT.SRVY_TRGT_TYCD = 'ALL' THEN '1' ELSE FN_LIKE_VAL(TRGT.SRVY_TRGT_TYCD) END AND AUTHRT.AUTHRT_CD NOT IN ('AUDIT', 'OBSVR', 'GUEST') JOIN TB_LMS_USER_AUTHRT USR_AUTHRT ON AUTHRT.AUTHRT_ID = USR_AUTHRT.AUTHRT_ID JOIN TB_LMS_SBJCT SBJCT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID AND SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' LEFT JOIN TB_LMS_ATNDLC ATNDLC ON SBJCT.SBJCT_ID = ATNDLC.SBJCT_ID AND ATNDLC.AUDITYN = 'N' AND USR_AUTHRT.USER_ID = ATNDLC.USER_ID LEFT JOIN TB_LMS_SBJCT_ADM SBJCT_ADM ON SBJCT.SBJCT_ID = SBJCT_ADM.SBJCT_ID AND SBJCT_ADM.SBJCT_ADM_TYCD LIKE FN_LIKE_VAL(TRGT.SRVY_TRGT_TYCD) AND USR_AUTHRT.USER_ID = SBJCT_ADM.USER_ID LEFT JOIN TB_LMS_USER STDNT ON ATNDLC.USER_ID = STDNT.USER_ID AND STDNT.USER_ID_STSCD = 'APRV_CMPTN' LEFT JOIN TB_LMS_USER PROF ON SBJCT_ADM.USER_ID = PROF.USER_ID AND PROF.USER_ID_STSCD = 'APRV_CMPTN' LEFT JOIN TB_LMS_USER ADM ON USR_AUTHRT.USER_ID = ADM.USER_ID WHERE SRVY.SRVY_GBNCD = 'HOMEPAGE_SRVY' AND SRVY.SRVY_TYCD = 'SRVY_WHOL' AND SRVY.DELYN = 'N' AND SRVY.USEYN = 'Y' AND SRVY.SRVY_QSTNS_CMPTNYN = 'Y'
AND ORG.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND CHRT.DGRS_YR = #{dgrsYr}
AND LOWER(SRVY.SRVY_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
AND (TRGT.SRVY_TRGT_TYCD LIKE FN_LIKE_VAL(#{searchText}) OR TRGT.SRVY_TRGT_TYCD = 'ALL') GROUP BY SRVY.SRVY_ID )
